# Termicolor dark for PSReadLine - generated by https://github.com/repraze/termicolor
# Dot-source this file from your PowerShell profile:  . "$HOME\termicolor-dark.ps1"
# Uses 24-bit color escapes; needs a truecolor terminal (Windows Terminal, VS Code, most modern terminals).

& {
    $e = [char]27
    $colors = @{
        Default            = "${e}[38;2;250;250;250m"
        Comment            = "${e}[38;2;163;163;163m"
        Keyword            = "${e}[38;2;187;122;255m"
        String             = "${e}[38;2;53;224;163m"
        Operator           = "${e}[38;2;250;250;250m"
        Variable           = "${e}[38;2;255;96;212m"
        Command            = "${e}[38;2;77;145;255m"
        Parameter          = "${e}[38;2;46;223;235m"
        Type               = "${e}[38;2;242;194;36m"
        Number             = "${e}[38;2;255;146;67m"
        Member             = "${e}[38;2;250;250;250m"
        Emphasis           = "${e}[38;2;187;122;255;1m"
        Error              = "${e}[38;2;255;76;130m"
        ContinuationPrompt = "${e}[38;2;115;115;115m"
        Selection          = "${e}[38;2;250;250;250;48;2;67;52;85m"
    }

    $psrl = (Get-Module PSReadLine).Version
    if ($psrl -ge [version]"2.1.0") {
        $colors.InlinePrediction = "${e}[38;2;115;115;115m"
    }
    if ($psrl -ge [version]"2.2.0") {
        $colors.ListPrediction = "${e}[38;2;187;122;255m"
        $colors.ListPredictionSelected = "${e}[48;2;38;38;38m"
    }

    Set-PSReadLineOption -Colors $colors
}
